#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Immersive

COMPONENT Scripting : 1

DEF OUT Script {
  inputOutput MFString out [
    "B ABSTRACT_NODES boolean true",
    "B CONCRETE_NODES boolean true",
    "B EXTERNAL_INTERACTIONS boolean true",
    "B PROTOTYPE_CREATE boolean true",
    "B DOM_IMPORT boolean true",
    "B XML_ENCODING boolean true",
    "B CLASSIC_VRML_ENCODING boolean true",
    "B BINARY_ENCODING boolean false",
    "R Shading string \"GOURAUD\"",
    "R MaxTextureSize number -",
    "R TextureUnits number -",
    "R MaxLights number -",
    "R Antialiased boolean -",
    "R ColorDepth number -",
    "R TextureMemory number -",
    "R ContentScale number 1",
    "R LogarithmicDepthBuffer boolean false",
    "R MaxAnisotropicDegree number -",
    "R MaxSamples number -",
    "R Multisampling number -",
    "R PixelsPerPoint number 1.3333333333333333",
    "R SoundDestinations number 0",
    "R XRSession boolean false"
  ]

  url "ecmascript:
    function initialize () {
      var r = [];
      var gpu = ['MaxTextureSize', 'TextureUnits', 'MaxLights', 'ColorDepth', 'TextureMemory', 'MaxAnisotropicDegree', 'MaxSamples', 'Antialiased', 'Multisampling'];
      function list (o, get, tag) {
        Array .from (o .getFieldDefinitions ()) .forEach (function (d) {
          var v;
          try { v = get (d .name); } catch (e) { v = 'THROW ' + e .message; }
          r .push (tag + ' ' + d .name + ' ' + typeof v + ' ' + (gpu .indexOf (d .name) >= 0 ? '-' : v !== null && typeof v === 'object' ? String (v) : JSON .stringify (v)));
        });
      }
      list (Browser .getBrowserProperties (), function (n) { return Browser .getBrowserProperty (n); }, 'B');
      list (Browser .getRenderingProperties (), function (n) { return Browser .getRenderingProperty (n); }, 'R');
      out = new MFString (... r);
    }
  "
}
